// ---- Build Prompt (Versuch 1) ----
const payload = ($('Webhook').first().json.body) || $('Webhook').first().json || {};

const DIFFICULTY_CONFIG = {
  easy:   { maxAttempts: 3, numericTolerance: 0.01, minRows: 5,  maxRows: 15, maxSteps: 1, complexity: "einfache Ein-Schritt-Aufgabe" },
  medium: { maxAttempts: 3, numericTolerance: 0.01, minRows: 10, maxRows: 25, maxSteps: 2, complexity: "zweistufige Aufgabe" },
  hard:   { maxAttempts: 2, numericTolerance: 0.01, minRows: 15, maxRows: 40, maxSteps: 3, complexity: "mehrstufige Aufgabe" }
};
const difficulty = ["easy","medium","hard"].includes(payload.difficulty) ? payload.difficulty : "easy";
const config = DIFFICULTY_CONFIG[difficulty];

const LEARNING_GOALS = {
  finanzabschluss: "Finanzabschluss", buchhaltung: "Buchhaltung", controlling: "Controlling",
  reporting: "Reporting", kostenrechnung: "Kostenrechnung", konsolidierung: "Konsolidierung",
  steuern: "Steuern", treasury: "Treasury"
};
const learningGoal = payload.learningGoal === "other"
  ? (payload.learningGoalCustom || "Allgemeines Finance-Thema")
  : (LEARNING_GOALS[payload.learningGoal] || payload.learningGoal || "Allgemeines Finance-Thema");

const techLabel = payload.technologyLabel || payload.technologyCustom || "KI-Technologie";
const techContext = payload.technologyWhatsNew ? ("Kontext zur Technologie: " + payload.technologyWhatsNew) : "";

const systemPrompt = `Du bist Spiel-Generator fuer "Excel-Prompt-Challenges" der Lufthansa Finance Training Academy. Zielgruppe: eine Controllerin, nicht-technisch. Sie loest die Aufgabe AUSSCHLIESSLICH per KI-Prompt an ${techLabel} — sie tippt NICHT selbst in Zellen und bearbeitet die Tabelle NICHT manuell.

Erzeuge EINE realistische, finanznahe Tabellen-Aufgabe. Gib AUSSCHLIESSLICH valides JSON zurueck, KEINE Markdown-Code-Bloecke, exakt in diesem Format:
{
 "task": "<deutsche Aufgabenstellung, 2-4 Saetze. Beschreibt das gewuenschte ERGEBNIS der Tabelle und macht explizit klar, dass die Nutzerin dies erreicht, indem sie ${techLabel} einen Prompt gibt — NICHT durch manuelles Sortieren/Rechnen. Formuliere ergebnisorientiert (z.B. 'Am Ende soll die Tabelle ... sein'), nicht als direkte Handlungsanweisung an die Nutzerin.>",
 "initialData": { "headers": ["<Spalte>", "..."], "rows": [["<zelle>", 123], "..."] },
 "transformSteps": [ <1 bis N Schritte aus dem erlaubten Vokabular> ],
 "evaluationCriteria": [ { "id": "<kurzer_slug>", "description": "<deutsch, wird im Ergebnis angezeigt>", "weight": <zahl>, "columns": ["<Header>"] } ],
 "samplePrompt": "<deutscher Beispiel-Prompt, der ${techLabel} DIREKT namentlich anspricht und die Aufgabe loest. Dies ist das zentrale Lern-Element: er zeigt der Nutzerin, wie ein guter Prompt an ${techLabel} aussieht.>"
}

DIDAKTISCHES ZIEL (Lernziel: "${learningGoal}", Technologie: "${techLabel}"):
- Der "samplePrompt" ist das wichtigste Lern-Artefakt. Er MUSS ${techLabel} beim Namen ansprechen und vormachen, wie die Nutzerin die Aufgabe per Prompt loest.
- Die "task" muss das "Ich schreibe einen Prompt statt selbst zu tippen"-Prinzip vermitteln und ${techLabel} als das Werkzeug benennen, das die Arbeit ausfuehrt.
- Ist "${learningGoal}" ein Finanz-Fachthema (z.B. Buchhaltung, Controlling), spiegle es zusaetzlich im Tabellen-Inhalt (Datenart, Spalten). Ist es ein Konzept-/Werkzeug-Ziel (z.B. "was ist ein Prompt", "was ist ${techLabel}"), nutze allgemeine, realistische Finance-Controlling-Daten und trage das Lernziel ueber task + samplePrompt.

ERLAUBTES transformSteps-Vokabular (NUR diese drei, nichts anderes):
- { "op": "sort", "column": "<Header>", "direction": "asc|desc" }
- { "op": "filter", "column": "<Header>", "operator": "eq|gt|lt|contains", "value": <wert> }
- { "op": "derived_column", "newColumn": "<neuer Header>", "operation": "add|subtract|multiply|divide", "operands": ["<Header>", "<Header>"] }

HARTE REGELN:
- Berechne NIEMALS selbst das Ergebnis der Transformation. Liefere NUR initialData + transformSteps. Die Loesung (solutionData) wird deterministisch im Code berechnet, NICHT von dir.
- Jede "column"/"operands" in transformSteps und jede "columns" in evaluationCriteria MUSS ein exakter Header aus initialData.headers sein. Ein Kriterium darf zusaetzlich eine per derived_column erzeugte newColumn referenzieren.
- Der "samplePrompt" MUSS den Namen "${techLabel}" enthalten.
- Die Summe aller "weight" MUSS exakt 1.0 ergeben.
- initialData braucht zwischen ${config.minRows} und ${config.maxRows} Datenzeilen und maximal ${config.maxSteps} transformStep(s) (${config.complexity}).
- Realistische deutsche Finanz-/Controlling-Daten (Betraege, Kostenstellen, Perioden, Belege).
- Zahlen als echte JSON-Zahlen ausgeben, nicht als Strings.
- Die Aufgabe muss durch die transformSteps eine SICHTBARE Veraenderung der Tabelle bewirken (keine triviale/leere Transformation).

Schwierigkeit: ${difficulty}.`;

const userPrompt = `Erzeuge jetzt eine Excel-Prompt-Challenge fuer das Lernziel "${learningGoal}" mit der Technologie "${techLabel}", Schwierigkeit "${difficulty}".

Wichtig: "${techLabel}" muss im samplePrompt namentlich angesprochen werden, und die task muss klar machen, dass die Nutzerin die Aufgabe per Prompt an ${techLabel} loest (nicht manuell). Gib ausschliesslich das JSON im vorgegebenen Format zurueck.`;

const llm_body = {
  model: "OpenAI GPT OSS 120b KI:Inferenz.nrw",
  messages: [
    { role: "system", content: systemPrompt },
    { role: "user", content: userPrompt }
  ],
  temperature: 0.4
};

return [{ json: { llm_body, attempt: 1, difficulty, config, payload } }];

// ---- Process & Validate ----
const resp = $json;
const bp = $('Build Prompt').first().json;
const payload = bp.payload;
const config = bp.config;
const attempt = bp.attempt;

function fail(errors, raw) {
  return [{ json: { valid: false, errors, game_json: null, payload, config,
    meta: { attempt, model: bp.llm_body.model }, raw } }];
}

// --- parse LLM content ---
let content = "";
try { content = resp.choices[0].message.content; }
catch (e) { return fail(["LLM-Antwort ohne choices/content"], resp); }
const usage = resp.usage || null;

let data;
try {
  const cleaned = String(content).replace(/```json/gi, "").replace(/```/g, "").trim();
  data = JSON.parse(cleaned);
} catch (e) { return fail(["LLM-Ausgabe ist kein valides JSON: " + e.message], content); }

// --- structural checks ---
let errors = [];
if (typeof data.task !== "string" || data.task.trim().length < 10) errors.push("task fehlt oder zu kurz");
const initial = data.initialData;
if (!initial || !Array.isArray(initial.headers) || !Array.isArray(initial.rows)) errors.push("initialData ungueltig");
if (!Array.isArray(data.transformSteps) || data.transformSteps.length < 1) errors.push("transformSteps fehlt/leer");
if (!Array.isArray(data.evaluationCriteria) || data.evaluationCriteria.length < 1) errors.push("evaluationCriteria fehlt/leer");
if (typeof data.samplePrompt !== "string" || data.samplePrompt.trim().length < 5) errors.push("samplePrompt fehlt");
if (errors.length) return fail(errors, data);

const nRows = initial.rows.length;
if (nRows < config.minRows || nRows > config.maxRows) errors.push("Zeilenanzahl " + nRows + " ausserhalb " + config.minRows + "-" + config.maxRows);
if (data.transformSteps.length > config.maxSteps) errors.push("Zu viele transformSteps (" + data.transformSteps.length + " > " + config.maxSteps + ")");

// --- helpers ---
function colIndex(headers, name) {
  const t = String(name).trim().toLowerCase();
  return headers.findIndex(h => String(h).trim().toLowerCase() === t);
}
function toNum(v) {
  if (v === null || v === undefined || v === "") return null;
  const n = Number(String(v).replace(",", "."));
  return isNaN(n) ? null : n;
}

// --- validate transform columns exist ---
for (const step of data.transformSteps) {
  if (step.op === "sort" || step.op === "filter") {
    if (colIndex(initial.headers, step.column) < 0) errors.push("Spalte '" + step.column + "' fuer " + step.op + " nicht vorhanden");
    if (step.op === "sort" && !["asc","desc"].includes(step.direction)) errors.push("sort ohne gueltige direction");
    if (step.op === "filter" && !["eq","gt","lt","contains"].includes(step.operator)) errors.push("filter ohne gueltigen operator");
  } else if (step.op === "derived_column") {
    for (const oc of (step.operands || [])) if (colIndex(initial.headers, oc) < 0) errors.push("Operand-Spalte '" + oc + "' nicht vorhanden");
    if (!step.newColumn) errors.push("derived_column ohne newColumn");
    if (!["add","subtract","multiply","divide"].includes(step.operation)) errors.push("derived_column ohne gueltige operation");
  } else {
    errors.push("Unbekannte op '" + step.op + "'");
  }
}
if (errors.length) return fail(errors, data);

// --- applyTransform (deterministische Loesungsberechnung) ---
function applyTransform(table, steps) {
  let headers = table.headers.slice();
  let rows = table.rows.map(r => r.slice());
  for (const step of steps) {
    if (step.op === "sort") {
      const ci = colIndex(headers, step.column);
      const dir = step.direction === "asc" ? 1 : -1;
      rows.sort((a, b) => {
        const na = toNum(a[ci]), nb = toNum(b[ci]);
        if (na !== null && nb !== null) return (na - nb) * dir;
        return String(a[ci]).localeCompare(String(b[ci])) * dir;
      });
    } else if (step.op === "filter") {
      const ci = colIndex(headers, step.column);
      rows = rows.filter(r => {
        const cell = r[ci];
        const cn = toNum(cell), vn = toNum(step.value);
        switch (step.operator) {
          case "eq": return String(cell).trim().toLowerCase() === String(step.value).trim().toLowerCase();
          case "gt": return cn !== null && vn !== null && cn > vn;
          case "lt": return cn !== null && vn !== null && cn < vn;
          case "contains": return String(cell).toLowerCase().includes(String(step.value).toLowerCase());
          default: return true;
        }
      });
    } else if (step.op === "derived_column") {
      const ai = colIndex(headers, step.operands[0]);
      const bi = colIndex(headers, step.operands[1]);
      headers = headers.concat([step.newColumn]);
      rows = rows.map(r => {
        const x = toNum(r[ai]), y = toNum(r[bi]);
        let v = null;
        if (x !== null && y !== null) {
          switch (step.operation) {
            case "add": v = x + y; break;
            case "subtract": v = x - y; break;
            case "multiply": v = x * y; break;
            case "divide": v = y !== 0 ? x / y : null; break;
          }
        }
        return r.concat([v]);
      });
    }
  }
  return { headers, rows };
}

let solutionData;
try { solutionData = applyTransform(initial, data.transformSteps); }
catch (e) { return fail(["applyTransform fehlgeschlagen: " + e.message], data); }

// --- criteria checks (gegen solutionData.headers, da derived columns erlaubt) ---
for (const c of data.evaluationCriteria) {
  if (!Array.isArray(c.columns) || c.columns.length === 0) { errors.push("Kriterium '" + (c.id || "?") + "' ohne columns"); continue; }
  for (const col of c.columns) if (colIndex(solutionData.headers, col) < 0) errors.push("Kriterium-Spalte '" + col + "' nicht in Loesung");
  if (typeof c.weight !== "number") errors.push("Kriterium '" + (c.id || "?") + "' ohne numerisches weight");
}
const wsum = data.evaluationCriteria.reduce((s, c) => s + (Number(c.weight) || 0), 0);
if (Math.abs(wsum - 1) > 0.001) errors.push("Gewichtssumme " + wsum + " != 1.0");

// --- non-trivial: Loesung unterscheidet sich in gescorten Spalten ---
const rowOrderMatters = data.transformSteps.some(s => s.op === "sort");
const scoredCols = Array.from(new Set([].concat.apply([], data.evaluationCriteria.map(c => c.columns))));
function project(tbl) {
  return tbl.rows.map(r => scoredCols.map(col => {
    const ci = colIndex(tbl.headers, col);
    return ci >= 0 ? String(r[ci]) : "";
  }).join("|"));
}
const pa = project(initial);
const pb = project(solutionData);
const differs = rowOrderMatters
  ? JSON.stringify(pa) !== JSON.stringify(pb)
  : JSON.stringify(pa.slice().sort()) !== JSON.stringify(pb.slice().sort());
if (!differs) errors.push("solutionData unterscheidet sich nicht von initialData in gescorten Spalten (triviale/unloesbare Aufgabe)");

if (errors.length) return fail(errors, data);

// --- assemble ExcelChallengeData ---
const game_json = {
  task: data.task.trim(),
  initialData: initial,
  solutionData: solutionData,
  evaluationCriteria: data.evaluationCriteria.map(c => ({
    id: String(c.id || ""), description: String(c.description || ""),
    weight: Number(c.weight), columns: c.columns
  })),
  evaluationConfig: { rowOrderMatters, columnOrderMatters: false, numericTolerance: config.numericTolerance },
  maxAttempts: config.maxAttempts,
  samplePrompt: data.samplePrompt.trim()
};

return [{ json: { valid: true, errors: [], game_json, payload, config,
  meta: { attempt, model: bp.llm_body.model, tokens: usage, transformSteps: data.transformSteps }, raw: null } }];

// ---- Build Repair Prompt (Versuch 2) ----
const prev = $('Process & Validate 1').first().json;
const bp = $('Build Prompt').first().json;
const errors = prev.errors || [];
const rawPrev = prev.raw;

const repairSystem = bp.llm_body.messages[0].content; // gleiche Spec
const repairUser = "Dein vorheriger Versuch war UNGUELTIG. Behobene Fehler noetig:\n- "
  + errors.join("\n- ")
  + "\n\nDein vorheriger (fehlerhafter) Output:\n" + JSON.stringify(rawPrev)
  + "\n\nKorrigiere GENAU diese Fehler und gib erneut AUSSCHLIESSLICH das valide JSON im vorgegebenen Format zurueck.";

